// @interlace/landing-template v1.1.1 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/landing-template
// What changed since: https://ds.interlace.tools/c/landing-template#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — LandingTemplate
 *
 * Marketing landing page surface. Composes Topbar + Hero +
 * (optional) FeatureGrid + (optional) TestimonialGrid + (optional)
 * PricingTable + (optional) FAQ + CTASection + Footer — each in its own
 * SectionBoundary so the page streams section-by-section.
 *
 * Every section is optional via props; pass only what you need. The
 * Topbar + Footer are required (every landing page has them).
 *
 * ## MIN_VIEWPORT — 320
 */

import * as React from 'react';

import { cn } from '@/lib/utils';
import { SectionBoundary } from '@/components/ui/section-boundary';
import { Topbar } from '@/components/ui/patterns/topbar';
import { Footer } from '@/components/ui/patterns/footer';
import { Skeleton } from '@/components/ui/skeleton';
import { Stack } from '@/components/ui/stack';
import { Container } from '@/components/ui/container';

export const MIN_VIEWPORT = 320 as const;

interface LandingTemplateProps extends React.ComponentProps<'div'> {
  /** Topbar props. */
  topbar: React.ComponentProps<typeof Topbar>;
  /** Hero section (consumer-supplied — pass the configured Hero pattern). */
  hero: React.ReactNode;
  /** Optional features section. */
  features?: React.ReactNode;
  /** Optional testimonials section. */
  testimonials?: React.ReactNode;
  /** Optional pricing section. */
  pricing?: React.ReactNode;
  /** Optional FAQ section. */
  faq?: React.ReactNode;
  /** Optional CTA section before the footer. */
  cta?: React.ReactNode;
  /** Footer props. */
  footer: React.ComponentProps<typeof Footer>;
  /** Extra arbitrary sections — rendered between hero and features. */
  children?: React.ReactNode;
}

function LandingTemplate({
  topbar,
  hero,
  features,
  testimonials,
  pricing,
  faq,
  cta,
  footer,
  children,
  className,
  ...props
}: LandingTemplateProps) {
  return (
    <div
      data-slot="landing-template"
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn('bg-background text-foreground', className)}
      {...props}
    >
      <Topbar {...topbar} />

      {/* Every section below sits inside <main>, and it is not decoration.
          Topbar emits <header>, Footer emits <footer>, and SectionBoundary
          renders `display: contents` — so without this element the entire body
          of the page was outside any landmark, and SkipLink had nothing to skip
          TO. AuthorTemplate / TagTemplate / StatsTemplate already wrap; this is
          the marketing page catching up. */}
      <main id="main">
        <SectionBoundary name="landing-hero" skeletonVariant="page-header">
          {hero}
        </SectionBoundary>

        {children}

        {features ? (
          <SectionBoundary
            name="landing-features"
            skeletonVariant="article-card"
          >
            {features}
          </SectionBoundary>
        ) : null}

        {testimonials ? (
          <SectionBoundary
            name="landing-testimonials"
            skeletonVariant="article-card"
          >
            {testimonials}
          </SectionBoundary>
        ) : null}

        {pricing ? (
          <SectionBoundary name="landing-pricing" skeletonVariant="card">
            {pricing}
          </SectionBoundary>
        ) : null}

        {faq ? (
          <SectionBoundary name="landing-faq" skeletonVariant="card">
            {faq}
          </SectionBoundary>
        ) : null}

        {cta ? (
          <SectionBoundary name="landing-cta" skeletonVariant="card">
            {cta}
          </SectionBoundary>
        ) : null}
      </main>

      <Footer {...footer} />
    </div>
  );
}
LandingTemplate.displayName = 'LandingTemplate';

/**
 * Page-level loading state — the full-page silhouette of
 * `<LandingTemplate>`, not a single rect. Rendered by the consumer while
 * the whole route's data is in flight (`loading.tsx` in Next.js), or as
 * a `<SectionBoundary skeleton={…}>` override.
 *
 * Shapes mirror the real layout so the swap is CLS-neutral (R23). One
 * `role="status"` region for the page; inner skeletons pass
 * `label={null}` so screen readers hear one announcement, not ten.
 */
function LandingTemplateSkeleton({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="landing-template-skeleton"
      data-min-viewport={String(MIN_VIEWPORT)}
      role="status"
      aria-busy="true"
      aria-label="Loading page…"
      className={cn('bg-background text-foreground', className)}
      {...props}
    >
      <Skeleton
        variant="rect"
        className="h-14 w-full rounded-none"
        label={null}
      />
      <Container size="content">
        <Stack gap="xl" className="py-xl">
          <Skeleton variant="page-header" label={null} />
          <Skeleton variant="article-card" count={3} label={null} />
          <Skeleton variant="card" count={2} label={null} />
        </Stack>
      </Container>
    </div>
  );
}
LandingTemplateSkeleton.displayName = 'LandingTemplateSkeleton';
LandingTemplate.Skeleton = LandingTemplateSkeleton;

export { LandingTemplate };
export type { LandingTemplateProps };
